<div class="min-w-0" x-data="{value:'',visible:false,generated:false,checks(){return {length:this.value.length>=8,upper:/[A-Z]/.test(this.value),lower:/[a-z]/.test(this.value),number:/[0-9]/.test(this.value),symbol:/[^A-Za-z0-9]/.test(this.value)}},generate(){const sets=['ABCDEFGHJKLMNPQRSTUVWXYZ','abcdefghijkmnopqrstuvwxyz','23456789','@#$%&*!'];const all=sets.join('');const bytes=new Uint32Array(12);crypto.getRandomValues(bytes);let chars=sets.map((set,i)=>set[bytes[i]%set.length]);for(let i=4;i<12;i++)chars.push(all[bytes[i]%all.length]);for(let i=chars.length-1;i>0;i--){const b=new Uint32Array(1);crypto.getRandomValues(b);const j=b[0]%(i+1);[chars[i],chars[j]]=[chars[j],chars[i]]}this.value=chars.join('');this.generated=true}">
    <label class="sr-only" for="{{ $id }}">{{ $label ?? 'Contraseña segura' }}</label>
    <div class="flex min-w-0 gap-1"><input id="{{ $id }}" class="field min-w-0 flex-1" name="password" x-model="value" x-bind:type="visible ? 'text' : 'password'" {{ !empty($required) ? 'required' : '' }} autocomplete="{{ $autocomplete ?? 'new-password' }}" placeholder="{{ $placeholder ?? 'Contraseña segura' }}"><button type="button" @click="visible=!visible" class="shrink-0 rounded-lg border border-[#B1D0E2] px-2 text-xs font-semibold text-[#018FC7]" x-text="visible ? 'Ocultar' : 'Ver'" aria-label="Mostrar u ocultar contraseña"></button><button type="button" @click="generate()" class="shrink-0 rounded-lg border border-[#B1D0E2] px-2 text-xs font-semibold text-[#018FC7]">Generar</button></div>
    <ul class="mt-2 grid grid-cols-2 gap-x-3 gap-y-1 text-[11px] text-slate-500 sm:grid-cols-3" aria-live="polite"><template x-for="[label,ok] of Object.entries({Longitud:checks().length,Mayúscula:checks().upper,Minúscula:checks().lower,Número:checks().number,Símbolo:checks().symbol})" :key="label"><li class="flex items-center gap-1" :class="ok?'font-semibold text-emerald-700':''"><span x-text="ok?'✓':'○'"></span><span x-text="label"></span></li></template></ul>
</div>
